import{_ as e,c as o,o as t,a2 as a}from"./chunks/framework.DdOM6S6U.js";const g=JSON.parse('{"title":"Operations Commands","description":"","frontmatter":{"sidebarPos":12,"sidebarTitle":"Overview","sidebarGroupTitle":"Operations"},"headers":[],"relativePath":"guide/console/operations/overview.md","filePath":"guide/console/operations/overview.md","lastUpdated":1778363927000}'),r={name:"guide/console/operations/overview.md"},s=a('<h1 id="operations-commands" tabindex="-1">Operations Commands <a class="header-anchor" href="#operations-commands" aria-label="Permalink to &quot;Operations Commands&quot;">​</a></h1><p>Operations commands manage the Modularous <strong>Operations</strong> pipeline — a queued job system for processing module operations (long-running tasks generated via <code>modularous:make:operation</code>).</p><div class="warning custom-block"><p class="custom-block-title">Internal commands</p><p>Both commands have <code>$hidden = true</code> and are not listed in <code>php artisan list</code>. They are intended for advanced use and internal tooling — in normal development you trigger operations from domain code, not the CLI.</p></div><table><thead><tr><th>Command</th><th>Description</th></tr></thead><tbody><tr><td><a href="/guide/console/operations/process-operations">modularous:operations:process</a></td><td>Dispatch or run pending module operations</td></tr><tr><td><a href="/guide/console/operations/publish-operations">modularous:publish:operations</a></td><td>Publish the operations vendor assets</td></tr></tbody></table><h2 id="when-you-might-need-these" tabindex="-1">When You Might Need These <a class="header-anchor" href="#when-you-might-need-these" aria-label="Permalink to &quot;When You Might Need These&quot;">​</a></h2><p>Normal flow: code dispatches an operation → Laravel queues it → a queue worker picks it up. These commands are escape hatches for when that flow is interrupted.</p><table><thead><tr><th>Situation</th><th>Command</th><th>Notes</th></tr></thead><tbody><tr><td>Queue worker is down and pending operations are piling up</td><td><code>modularous:operations:process</code></td><td>One-shot run outside the queue</td></tr><tr><td>Testing / reproducing a stuck operation locally</td><td><code>modularous:operations:process</code></td><td>Run synchronously to see exceptions</td></tr><tr><td>Installing Modularous from source and assets haven&#39;t been published yet</td><td><code>modularous:publish:operations</code></td><td>Usually covered by <code>modularous:install</code></td></tr></tbody></table><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./../generators/make-operation"><code>modularous:make:operation</code></a> — scaffold a new operation class</li><li><a href="https://laravel.com/docs/queues" target="_blank" rel="noreferrer">Queue workers</a> — the default pipeline</li></ul>',9),d=[s];function n(i,l,u,c,p,h){return t(),o("div",null,d)}const b=e(r,[["render",n]]);export{g as __pageData,b as default};
